// If a sign-in popup lands here instead of /auth/callback.html (a redirect allow-list slip, build log B42),
// finish the sign-in anyway: hand the code to the panel that opened the popup, exactly as the callback page does.
{
  const params = new URLSearchParams(location.search)
  const code = params.get('code')
  const error = params.get('error_description') || params.get('error')
  if ((code || error) && window.opener) {
    ;(window.opener as Window).postMessage({ type: 'yrS4:auth', code, error }, location.origin)
    history.replaceState(null, '', location.pathname)
    document.body.innerHTML = `<p style="font: 16px system-ui; padding: 24px">${error ? 'Sign-in failed: ' + error : 'Signed in. You can close this window.'}</p>`
    if (!error) setTimeout(() => window.close(), 300)
  } else if (code || error) {
    history.replaceState(null, '', location.pathname)
  }
}

// Builds the bookmarklet link for the package typed in the box.
const a = document.getElementById('bm') as HTMLAnchorElement
const input = document.getElementById('pkg') as HTMLInputElement
function update() {
  const pkg = input.value.trim()
  const origin = location.origin
  const js = `(function(){if(window.__yrS4)return;var s=document.createElement('script');s.src='${origin}/overlay/v1/yrS4.js?t='+Date.now();s.dataset.package=${JSON.stringify(pkg)};s.dataset.platform='${origin}';document.body.appendChild(s)})();`
  a.href = 'javascript:' + encodeURIComponent(js)
}
input.addEventListener('input', update)
update()
a.addEventListener('click', (e) => {
  if (location.pathname.startsWith('/')) {
    e.preventDefault()
    alert('Drag this link to your bookmarks bar, then click it while viewing a page of the book.')
  }
})
